import { Component, ComponentInterface, Element, h, Host, Prop, State, Watch } from '@stencil/core';
import { BrandLogoType, Breakpoint } from '../../types';
import { breakpointMapping } from '../../utils/breakpoint-mapping';

const logoCache = new Map<string, Promise<string>>();

/**
 * @slot default - default slot for the content of the brand logo
 */
@Component({
  tag: 'groupui-brand-logo',
  styleUrl: 'brand-logo.scss',
  shadow: true,
})
export class BrandLogo implements ComponentInterface {
  private baseUrl = 'https://assets.groupui.vwapps.run/latest/static/logos';
  private logoUrl = 'logo_vwgroup_global-navigation_small.svg';
  private largeLogoUrl = 'logo_vwgroup_global-navigation.svg';

  /**
   * type of the brand logo
   */
  @Prop({ reflect: true }) readonly type: BrandLogoType = 'entity';

  /**
   * breakpoint under which the layout switches to compact
   */
  @Prop({ reflect: true }) readonly breakpoint: Breakpoint = 'l';

  /**
   * Custom breakpoint in pixels under which the layout switches to compact
   * Overwrites the `breakpoint` property.
   */
  @Prop({ reflect: true }) readonly customBreakpoint: number;

  /**
   * @internal display the brand-logo in compact mode, regardless of the window-size
   */
  @Prop({ reflect: false }) readonly alwaysCompact: boolean;

  /**
   * URL of the logo. Enables interactivity.
   */
  @Prop({ reflect: false }) readonly href: string;

  /**
     @internal
     */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  @Element() host: HTMLElement;

  @State() logoContent: string;

  @State() collapsed: boolean;

  private resizeObserver: ResizeObserver;

  @Watch('collapsed')
  onCollapsedChanged() {
    this.collapsed ? this.host.classList.add('collapsed') : this.host.classList.remove('collapsed');
  }

  connectedCallback() {
    if (this.resizeObserver) {
      this.observeResize();
    }
  }

  componentDidLoad() {
    if (!this.alwaysCompact) {
      this.initResizeObserver();
      this.observeResize();
    }
  }

  async componentWillLoad() {
    this.collapsed = this.alwaysCompact;
    await this.loadAndCacheLogo();
  }

  private initResizeObserver() {
    this.resizeObserver = new ResizeObserver((element) => {
      const breakpoint = this.customBreakpoint ?? breakpointMapping.get(this.breakpoint);
      this.collapsed = element[0].contentRect.width < breakpoint;
    });
  }

  private observeResize() {
    this.resizeObserver.observe(window.document.documentElement);
  }

  async componentWillUpdate() {
    await this.loadAndCacheLogo();
  }

  disconnectedCallback() {
    this.resizeObserver?.disconnect();
  }

  private getLogoUrl() {
    const logoSource = document.querySelector('body').getAttribute('logo-source');
    const basePath = `${this.baseUrl}/vwgroup`;
    let logo = this.logoUrl;
    if ((this.type !== 'application' || !this.collapsed) && this.showLabel()) {
      logo = this.largeLogoUrl;
    }
    return `${logoSource ?? basePath}/${logo}`;
  }

  private async loadAndCacheLogo() {
    const logoUrl = this.getLogoUrl();
    if (!logoCache.has(logoUrl)) {
      const logoDataPromise = this.fetchLogoData(logoUrl);
      logoCache.set(logoUrl, logoDataPromise);
    }
    const logoData = await logoCache.get(logoUrl);
    this.logoContent = this.addTitle(logoData) ?? this.getFallbackImage();
  }

  private addTitle(logoData: string): string | undefined {
    if (!logoData) {
      return;
    }

    const parser = new DOMParser();
    const iconDom = parser.parseFromString(logoData, 'text/html');
    const svgElement = iconDom.querySelector('svg');

    if (!svgElement) {
      return;
    }

    svgElement.setAttribute('role', 'img');
    svgElement.setAttribute('aria-label', 'Volkswagen Group Logo');
    return iconDom.body.outerHTML;
  }

  private getFallbackImage() {
    return `<img src='data:,' alt='Volkswagen Group Logo'>`;
  }

  private async fetchLogoData(logoUrl: string): Promise<string | undefined> {
    try {
      const logoDataResponse = await fetch(logoUrl);
      if (logoDataResponse.ok) {
        return await logoDataResponse.text();
      }
    } catch (error) {
      console.error(error);
    }
  }

  private isDefaultSlotProvided(): boolean {
    return this.host.textContent.length > 0;
  }

  private content(): HTMLElement {
    const innerContent = (
      <div id="spacer">
        <div id="logo" innerHTML={this.logoContent}></div>
        {this.showLabel() && this.type === 'application' ? <groupui-divider inverted vertical /> : ''}
        {this.showLabel() && this.isDefaultSlotProvided() && (
          <span>
            <slot></slot>
          </span>
        )}
      </div>
    );

    if (this.href) {
      return <a href={this.href}>{innerContent}</a>;
    }
    return innerContent;
  }

  private showLabel() {
    return !this.iconOnly;
  }

  render() {
    return <Host>{this.content()}</Host>;
  }
}
